:root {
  --gold: #F4C752;
  --paper: #EEEAE3;
}
#stage { background: #000; color: var(--paper); }
.gl { position: absolute; left: 0; top: 0; width: 1080px; height: 1920px; }
.layer { position: absolute; inset: 0; }
/* Display: Bebas Neue, letters rising out of a mask that fits the caps exactly. */
.big { position: absolute; white-space: nowrap; font-family: "Bebas Neue"; font-weight: 400; line-height: 0.8; }
.mask { display: inline-block; overflow: hidden; vertical-align: top; padding-top: 0.03em; }
.ch { display: inline-block; will-change: transform; }
.photo .ch { color: transparent; -webkit-background-clip: text; background-clip: text; background-repeat: no-repeat; }
/* Running labels: Space Mono, tracked wide. */
.mono { position: absolute; white-space: nowrap; font: 700 30px/1 "Space Mono"; letter-spacing: 0.22em; text-transform: uppercase; color: rgba(238, 234, 227, 0.82); }
.hud { left: 0; width: 1080px; top: 238px; text-align: center; }
.rule { position: absolute; left: 90px; width: 900px; top: 292px; height: 2px; background: rgba(238, 234, 227, 0.16); }
.role { left: 0; width: 1080px; text-align: center; }
.gold { color: var(--gold); }
.dim { color: rgba(238, 234, 227, 0.55); }
.stack { position: absolute; left: 0; top: 0; width: 1080px; }
.lead { left: 92px; top: 0; }
.fadetop { -webkit-mask-image: linear-gradient(to bottom, transparent 300px, #000 470px); mask-image: linear-gradient(to bottom, transparent 300px, #000 470px); }
.mark { position: absolute; left: 460px; top: 650px; width: 160px; }
.bdg { position: absolute; transform-origin: 50% 50%; }
.endrule { position: absolute; left: 480px; width: 120px; top: 1172px; height: 3px; background: var(--gold); transform-origin: 50% 50%; }
.vignette { position: absolute; inset: 0; background: radial-gradient(ellipse 85% 70% at 50% 50%, rgba(0, 0, 0, 0) 58%, rgba(0, 0, 0, 0.42) 100%); pointer-events: none; }
.grain { position: absolute; inset: 0; opacity: 0.04; pointer-events: none; }

