const D = window.DATA;
const { clamp, lerp, span, expoOut, easeIn, easeOut, easeInOut, rand } = M;
const stage = document.getElementById("stage");
const FPS = D.fps;
const el = (tag, cls, parent = stage, text) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  parent.appendChild(e);
  return e;
};
const set = (n, s) => Object.assign(n.style, s);
const f2 = (v) => v.toFixed(2);

function track(t, keys) {
  if (t <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    const [t1, v1, ease = easeInOut] = keys[i];
    const [t0, v0] = keys[i - 1];
    if (t <= t1) return lerp(v0, v1, ease(span(t, t0, t1)));
  }
  return keys[keys.length - 1][1];
}
const springOut = (p) => (p >= 1 ? 1 : 1 - Math.exp(-6 * p) * Math.cos(8 * p));

function badgeSvg(size) {
  const pts = [];
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2 - Math.PI / 2;
    const r = i % 2 ? 10.1 : 11.6;
    pts.push(`${(12 + r * Math.cos(a)).toFixed(2)},${(12 + r * Math.sin(a)).toFixed(2)}`);
  }
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}"><polygon points="${pts.join(" ")}" fill="#0095F6" stroke="#0095F6" stroke-width="1.6" stroke-linejoin="round"/><path d="M7.4 12.4l3 3 6.2-6.5" fill="none" stroke="#fff" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}
const loadImg = (src) => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });

// ---------------------------------------------------------------------------------------
// His Instagram profile, drawn at 6x (390 x 845 points) for a sharp phone screen.
// Laid out in the points of a 390-wide screen and scaled to the 402 x 874 display.
const UI0 = { W: 390, H: 845 };
const TILES = [0, 130.5, 261];
function icon(ctx, d, x, y, size, { fill = false, color = "#f5f5f5", lw = 2 } = {}) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / 24, size / 24);
  ctx.lineWidth = lw;
  ctx.lineCap = ctx.lineJoin = "round";
  ctx.strokeStyle = ctx.fillStyle = color;
  for (const p of [].concat(d)) {
    if (typeof p === "string") ctx[fill ? "fill" : "stroke"](new Path2D(p));
    else p(ctx);
  }
  ctx.restore();
}
function badge(ctx, x, y, size) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(size / 24, size / 24);
  ctx.beginPath();
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2 - Math.PI / 2;
    const r = i % 2 ? 10.1 : 11.6;
    ctx[i ? "lineTo" : "moveTo"](12 + r * Math.cos(a), 12 + r * Math.sin(a));
  }
  ctx.closePath();
  ctx.fillStyle = ctx.strokeStyle = "#0095F6";
  ctx.lineWidth = 1.6;
  ctx.lineJoin = "round";
  ctx.fill();
  ctx.stroke();
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = 2.3;
  ctx.lineCap = "round";
  ctx.stroke(new Path2D("M7.4 12.4l3 3 6.2-6.5"));
  ctx.restore();
}
function cover(ctx, img, x, y, w, h) {
  const s = Math.max(w / img.width, h / img.height);
  const sw = w / s;
  const sh = h / s;
  ctx.drawImage(img, (img.width - sw) / 2, (img.height - sh) / 2, sw, sh, x, y, w, h);
}
function statusBar(ctx) {
  const txt = (s, x, y, size, weight) => {
    ctx.font = `${weight} ${size}px Inter`;
    ctx.fillStyle = "#fff";
    ctx.textBaseline = "top";
    ctx.fillText(s, x, y);
  };
  txt("9:41", 36, 17, 16, 600);
  ctx.fillStyle = "#fff";
  [[0, 9, 4], [5, 6.5, 6.5], [10, 4, 9], [15, 1.5, 11.5]].forEach(([x, y, h]) => { ctx.beginPath(); ctx.roundRect(288 + x, 19 + y, 3.4, h, 1); ctx.fill(); });
  icon(ctx, "M2 7.4a13 13 0 0 1 20 0M5.6 11a8 8 0 0 1 12.8 0M9.2 14.6a3 3 0 0 1 5.6 0", 312, 17, 20, { lw: 2.2, color: "#fff" });
  ctx.strokeStyle = "rgba(255,255,255,.5)";
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.roundRect(338, 19.5, 24, 11, 3.2); ctx.stroke();
  ctx.fillStyle = "#fff";
  ctx.beginPath(); ctx.roundRect(340, 21.5, 18, 7, 1.6); ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,.5)";
  ctx.beginPath(); ctx.roundRect(363.4, 23, 1.8, 4, 0.8); ctx.fill();
}
// bg: false leaves the background transparent and the island out, for the layers that lift off.
function drawProfile(ctx, img, k, bg = true) {
  ctx.save();
  if (bg) {
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  }
  ctx.scale(k, k);
  const txt = (s, x, y, size, weight = 400, color = "#f5f5f5") => {
    ctx.font = `${weight} ${size}px Inter`;
    ctx.fillStyle = color;
    ctx.textBaseline = "top";
    ctx.fillText(s, x, y);
    return ctx.measureText(s).width;
  };
  statusBar(ctx);
  icon(ctx, "M15 5l-7 7 7 7", 10, 57, 24);
  const uw = txt("thecinenhamila", 42, 60, 20, 700);
  badge(ctx, 42 + uw + 6, 61, 17);
  icon(ctx, ["M6 16V11a6 6 0 0 1 12 0v5l1.6 2H4.4z", "M10 20.5a2.2 2.2 0 0 0 4 0"], 314, 57, 24);
  icon(ctx, [(c) => { [5, 12, 19].forEach((cx) => { c.beginPath(); c.arc(cx, 12, 1.6, 0, Math.PI * 2); c.fill(); }); }], 350, 57, 24);
  // Header.
  ctx.save();
  ctx.beginPath(); ctx.arc(60, 148, 44, 0, Math.PI * 2); ctx.clip();
  cover(ctx, img.avatar, 16, 104, 88, 88);
  ctx.restore();
  txt("Cinen Hamila", 124, 110, 15, 600);
  [["3", "posts", 124], ["398", "followers", 194], ["181", "following", 284]].forEach(([n, l, x]) => { txt(n, x, 135, 17, 700); txt(l, x, 158, 13.5); });
  txt("CEO of Magik Management", 16, 208, 13.5, 400, "#a8a8a8");
  txt("🚀 I help businesses & creators turn content into clients", 16, 228, 12.9);
  txt("🧧 300+ clients under management", 16, 248, 12.9);
  txt("📈 Dm me ‘’BRAND’’ to get started", 16, 268, 12.9);
  const btn = (label, x, w, bg) => {
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.roundRect(x, 300, w, 34, 9); ctx.fill();
    ctx.font = "600 14px Inter";
    ctx.fillStyle = "#fff";
    ctx.textBaseline = "middle";
    ctx.textAlign = "center";
    ctx.fillText(label, x + w / 2, 317);
    ctx.textAlign = "left";
  };
  btn("Follow", 16, 152, "#0095F6");
  btn("Message", 174, 152, "#363636");
  btn("", 332, 42, "#363636");
  icon(ctx, [(c) => { c.beginPath(); c.arc(9, 8, 4, 0, Math.PI * 2); c.stroke(); }, "M2 21c0-4 3-6 7-6s7 2 7 6M19 8v6M16 11h6"], 344, 308, 18);
  // Highlights.
  ["p0b", "p1", "p1b", "p0", "avatar"].forEach((name, i) => {
    const cx = 49 + i * 79;
    ctx.save();
    ctx.beginPath(); ctx.arc(cx, 383, 33, 0, Math.PI * 2); ctx.clip();
    cover(ctx, img[name], cx - 33, 350, 66, 66);
    ctx.restore();
    ctx.strokeStyle = "#3a3a3a"; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(cx, 383, 35.2, 0, Math.PI * 2); ctx.stroke();
    ctx.font = "13px Inter"; ctx.textAlign = "center"; ctx.textBaseline = "top";
    ctx.fillText(["🚀", "🧧", "📈", "🎬", "✨"][i], cx, 426);
    ctx.textAlign = "left";
  });
  // Tabs and grid.
  icon(ctx, [(c) => { c.strokeRect(3, 3, 18, 18); }, "M9 3v18M15 3v18M3 9h18M3 15h18"], 53, 466, 24);
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 3, 18, 18, 4); c.stroke(); }, "M3 8h18M8 3l3 5M13 3l3 5", (c) => c.fill(new Path2D("M10 11.5v5l4.2-2.5z"))], 183, 466, 24);
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 3, 18, 18, 3); c.stroke(); c.beginPath(); c.arc(12, 10, 3, 0, Math.PI * 2); c.stroke(); }, "M6.5 19c1-3 3-4 5.5-4s4.5 1 5.5 4"], 313, 466, 24);
  ctx.fillStyle = "#f5f5f5"; ctx.fillRect(0, 500, 130, 1.5);
  ctx.fillStyle = "#262626"; ctx.fillRect(0, 501.5, 390, 0.5);
  ["p0", "p1", "p2"].forEach((name, i) => {
    cover(ctx, img[name], TILES[i], 503, 129, 172);
    icon(ctx, [(c) => { c.fillStyle = "rgba(0,0,0,.25)"; c.beginPath(); c.roundRect(7, 7, 13, 13, 2); c.fill(); c.stroke(); }, "M4 16V6a2 2 0 0 1 2-2h10"], TILES[i] + 104, 507, 18, { color: "#fff" });
  });
  // Bottom bar.
  ctx.fillStyle = "#262626"; ctx.fillRect(0, 782, 390, 0.5);
  icon(ctx, "M4 11l9-7 9 7v10H16v-6h-6v6H4z", 24, 796, 26, { fill: true });
  icon(ctx, [(c) => { c.beginPath(); c.arc(11.5, 11.5, 7, 0, Math.PI * 2); c.stroke(); }, "M17 17l5 5"], 100, 796, 26);
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 3, 20, 20, 5); c.stroke(); }, "M13 8v10M8 13h10"], 177, 796, 26);
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 3, 20, 20, 5); c.stroke(); }, "M3 9h20M9 3l3 6M15 3l3 6", (c) => c.fill(new Path2D("M11 12.5v6l5-3z"))], 254, 796, 26);
  ctx.save();
  ctx.beginPath(); ctx.arc(346, 810, 13, 0, Math.PI * 2); ctx.clip();
  cover(ctx, img.avatar, 333, 797, 26, 26);
  ctx.restore();
  ctx.strokeStyle = "#f5f5f5"; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(346, 810, 15, 0, Math.PI * 2); ctx.stroke();
  chrome(ctx, bg);
  ctx.restore();
}
// The Dynamic Island and the home indicator, in the same points.
function chrome(ctx, island = true) {
  ctx.fillStyle = "#000";
  if (island) { ctx.beginPath(); ctx.roundRect(134.5, 10.5, 121, 35.5, 17.75); ctx.fill(); }
  ctx.fillStyle = "rgba(255,255,255,0.92)";
  ctx.beginPath(); ctx.roundRect(130, 838.5, 130, 4.6, 2.3); ctx.fill();
}

// ---------------------------------------------------------------------------------------
// The other screens, in the same 390-point layout: the Magik Management site, and the DM thread
// where "BRAND" gets typed and sent.
const UIH = (874 * 390) / 402;
function drawSite(ctx, frame, k) {
  const W = ctx.canvas.width;
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, W, ctx.canvas.height);
  ctx.drawImage(frame, 0, 0, W, (W * frame.height) / frame.width);
  ctx.save();
  ctx.scale(k, k);
  const g = ctx.createLinearGradient(0, 0, 0, 56);
  g.addColorStop(0, "rgba(0,0,0,0.85)");
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 390, 56);
  statusBar(ctx);
  chrome(ctx);
  ctx.restore();
}
function drawBase(ctx, k) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  ctx.save();
  ctx.scale(k, k);
  chrome(ctx);
  ctx.restore();
}
const KEYS = ["QWERTYUIOP", "ASDFGHJKL", "ZXCVBNM"];
// s: { typed (letters of BRAND), sent, seen, typing, reply, press (the key held down) }
function drawDM(ctx, img, k, s) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  ctx.save();
  ctx.scale(k, k);
  const txt = (str, x, y, size, weight = 400, color = "#f5f5f5", align = "left") => {
    ctx.font = `${weight} ${size}px Inter`;
    ctx.fillStyle = color;
    ctx.textBaseline = "middle";
    ctx.textAlign = align;
    ctx.fillText(str, x, y);
    const w = ctx.measureText(str).width;
    ctx.textAlign = "left";
    return w;
  };
  const disc = (im, cx, cy, r) => {
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.clip();
    cover(ctx, im, cx - r, cy - r, 2 * r, 2 * r);
    ctx.restore();
  };
  statusBar(ctx);
  // Header.
  icon(ctx, "M15 5l-7 7 7 7", 8, 60, 24);
  disc(img.avatar, 52, 72, 16);
  const nw = txt("thecinenhamila", 77, 64, 15, 700);
  badge(ctx, 77 + nw + 4, 57, 14);
  txt("Cinen Hamila", 77, 82, 12, 400, "#a8a8a8");
  icon(ctx, "M5 4h3l2 5-2.5 1.5a11 11 0 0 0 6 6L15 14l5 2v3a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2", 300, 60, 24);
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(2, 6, 14, 12, 3); c.stroke(); }, "M16 10l6-3v10l-6-3"], 342, 60, 24);
  // The thread's header card.
  disc(img.avatar, 195, 166, 44);
  const cw = txt("Cinen Hamila", 195, 228, 18, 700, "#f5f5f5", "center");
  badge(ctx, 195 + cw / 2 + 4, 220, 16);
  txt("thecinenhamila · Instagram", 195, 252, 13, 400, "#a8a8a8", "center");
  txt("398 followers · 3 posts", 195, 270, 13, 400, "#a8a8a8", "center");
  ctx.fillStyle = "#262626";
  ctx.beginPath();
  ctx.roundRect(145, 286, 100, 30, 8);
  ctx.fill();
  txt("View profile", 195, 301, 13, 600, "#f5f5f5", "center");
  txt("Today 9:41", 195, 352, 11.5, 500, "#8e8e8e", "center");
  // Messages.
  if (s.sent) {
    ctx.font = "600 15px Inter";
    const bw = ctx.measureText("BRAND").width + 30;
    const g = ctx.createLinearGradient(0, 380, 0, 416);
    g.addColorStop(0, "#7a3cf0");
    g.addColorStop(1, "#4a5cf4");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.roundRect(374 - bw, 380, bw, 36, 18);
    ctx.fill();
    txt("BRAND", 374 - bw / 2, 398.5, 15, 600, "#fff", "center");
    if (s.seen) txt("Seen", 374, 428, 11, 500, "#8e8e8e", "right");
  }
  if (s.typing || s.reply) {
    disc(img.avatar, 27, 480, 11);
    ctx.fillStyle = "#262626";
    if (s.reply) {
      ctx.font = "400 15px Inter";
      const msg = "Let’s build it 🚀";
      const bw = ctx.measureText(msg).width + 30;
      ctx.beginPath();
      ctx.roundRect(46, 462, bw, 36, 18);
      ctx.fill();
      txt(msg, 61, 480.5, 15, 400, "#f5f5f5");
    } else {
      ctx.beginPath();
      ctx.roundRect(46, 462, 62, 36, 18);
      ctx.fill();
      ctx.fillStyle = "#a8a8a8";
      [62, 77, 92].forEach((x) => { ctx.beginPath(); ctx.arc(x, 480, 3.2, 0, Math.PI * 2); ctx.fill(); });
    }
  }
  // Composer.
  ctx.fillStyle = "#262626";
  ctx.beginPath();
  ctx.roundRect(10, 514, 370, 42, 21);
  ctx.fill();
  ctx.fillStyle = "#3f6ff0";
  ctx.beginPath();
  ctx.arc(31, 535, 16, 0, Math.PI * 2);
  ctx.fill();
  icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 7, 18, 13, 3); c.stroke(); c.beginPath(); c.arc(12, 13.5, 3.4, 0, Math.PI * 2); c.stroke(); }, "M9 7l1.5-2.5h3L15 7"], 22, 526, 18, { color: "#fff", lw: 2 });
  const typed = "BRAND".slice(0, s.typed);
  if (typed) {
    const w = txt(typed, 56, 535.5, 15.5, 500);
    ctx.fillStyle = "#3f8cff";
    ctx.fillRect(58 + w, 525, 2, 21);
    txt("Send", 364, 535.5, 15, 700, "#4c8dff", "right");
  } else {
    txt("Message...", 56, 535.5, 15.5, 400, "#8e8e8e");
    ctx.fillStyle = "#3f8cff";
    ctx.fillRect(55, 525, 2, 21);
    icon(ctx, ["M12 3a3 3 0 0 1 3 3v6a3 3 0 0 1-6 0V6a3 3 0 0 1 3-3", "M5 11a7 7 0 0 0 14 0M12 18v3"], 286, 524, 22);
    icon(ctx, [(c) => { c.beginPath(); c.roundRect(3, 3, 18, 18, 4); c.stroke(); c.beginPath(); c.arc(9, 9, 1.8, 0, Math.PI * 2); c.stroke(); }, "M4 18l5-5 4 4 3-3 5 5"], 318, 524, 22);
    icon(ctx, [(c) => { c.beginPath(); c.arc(12, 12, 9, 0, Math.PI * 2); c.stroke(); }, "M8.5 14.5a4.5 4.5 0 0 0 7 0", (c) => { c.beginPath(); c.arc(9, 10, 1, 0, Math.PI * 2); c.arc(15, 10, 1, 0, Math.PI * 2); c.fill(); }], 350, 524, 22);
  }
  // Keyboard, dark, with the key being pressed popped up.
  ctx.fillStyle = "#1c1c1e";
  ctx.fillRect(0, 566, 390, UIH - 566);
  const sug = typed ? ["“BRAND”", "Brand", "Brands"] : ["I", "The", "I’m"];
  sug.forEach((w, i) => txt(w, 65 + i * 130, 588, 15.5, 400, "#f5f5f5", "center"));
  ctx.fillStyle = "#3a3a3c";
  [130, 260].forEach((x) => ctx.fillRect(x, 578, 1, 20));
  const key = (x, y, w, label, special = false) => {
    const down = label === s.press;
    ctx.fillStyle = down ? "#8e8e93" : special ? "#3a3a3c" : "#5b5b5f";
    ctx.beginPath();
    ctx.roundRect(x, y, w, 42, 5.5);
    ctx.fill();
    if (label) txt(label, x + w / 2, y + 21.5, label.length > 1 ? 15 : 22, 400, "#fff", "center");
    if (down) {
      ctx.fillStyle = "#6e6e73";
      ctx.beginPath();
      ctx.roundRect(x - 7, y - 58, w + 14, 56, 9);
      ctx.fill();
      txt(label, x + w / 2, y - 31, 32, 400, "#fff", "center");
    }
  };
  KEYS[0].split("").forEach((c, i) => key(3 + i * 39, 612, 33, c));
  KEYS[1].split("").forEach((c, i) => key(22.5 + i * 39, 666, 33, c));
  key(3, 720, 42, "", true);
  icon(ctx, "M12 4l7 8h-4v7H9v-7H5z", 12.5, 729, 23, { color: "#fff", lw: 1.8 });
  KEYS[2].split("").forEach((c, i) => key(59 + i * 39, 720, 33, c));
  key(345, 720, 42, "", true);
  icon(ctx, ["M8 6h12v12H8l-5-6z", "M11 9.5l5 5M16 9.5l-5 5"], 354.5, 729, 23, { color: "#fff", lw: 1.8 });
  key(3, 774, 90, "123", true);
  key(99, 774, 192, "space");
  key(297, 774, 90, "return", true);
  chrome(ctx);
  ctx.restore();
}
// ---------------------------------------------------------------------------------------
// iPhone 16 Pro, Desert Titanium, at real scale (1 unit = 100 mm): a swept titanium band with
// contoured edges, flush front glass, a frosted back, the camera plateau with three lenses,
// flash and LiDAR, the buttons and Camera Control, antenna bands, the port and grilles.
const MM = 0.01;
const PW = 71.5 * MM;
const PH = 149.6 * MM;
const PD = 8.25 * MM;
const BODY_R = 20.2 * MM;
const UI = { W: 402, H: 874 };
const DISP = { w: 66.6 * MM, h: 144.8 * MM };

// A rounded rectangle with continuous (superellipse) corners, counter-clockwise, with outward
// normals and arc length.
function outline(w, h, r, n = 3.4, cseg = 40, lseg = 8) {
  const e = 2 / n;
  const C = [[w / 2 - r, h / 2 - r], [-(w / 2 - r), h / 2 - r], [-(w / 2 - r), -(h / 2 - r)], [w / 2 - r, -(h / 2 - r)]];
  const at = (q, th) => {
    const c = Math.cos(th);
    const s = Math.sin(th);
    return [C[q][0] + r * Math.sign(c) * Math.abs(c) ** e, C[q][1] + r * Math.sign(s) * Math.abs(s) ** e];
  };
  const P = [];
  for (let q = 0; q < 4; q++) {
