const cubicInOut = (p) => (p < 0.5 ? 4 * p * p * p : 1 - (-2 * p + 2) ** 3 / 2);
const cubicIn = (p) => p * p * p;
const quartOut = (p) => 1 - (1 - p) ** 4;
const backOut = (p, s = 1.6) => 1 + (s + 1) * (p - 1) ** 3 + s * (p - 1) ** 2;

