  camera.lookAt(target);
}
// Camera on a point of an object, `dist` along a direction given in the object's frame.
function closeUp(obj, local, nLocal, dist, shift = V(0, 0, 0)) {
  obj.updateMatrixWorld(true);
  const tgt = obj.localToWorld(local.clone());
  const n = nLocal.clone().applyQuaternion(obj.getWorldQuaternion(new THREE.Quaternion())).normalize();
  lookAt(tgt.clone().add(n.multiplyScalar(dist)).add(shift), tgt.clone().add(shift.clone().multiplyScalar(0.3)));
  return tgt;
}

// Studios for the PMREM environment: dark, a few large sources. The phone's has a warm strip on
// the right for a gold edge; the type's has a big warm key in front so gold faces read.
function studio(boxes) {
  const s = new THREE.Scene();
  s.background = new THREE.Color(0, 0, 0);
  s.add(new THREE.Mesh(new THREE.SphereGeometry(20, 32, 16), new THREE.MeshBasicMaterial({ color: new THREE.Color(0.012, 0.011, 0.01), side: THREE.BackSide })));
  for (const [w, h, pos, rgb] of boxes) {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(...rgb), side: THREE.DoubleSide }));
    m.position.set(...pos);
    m.lookAt(0, 0, 0);
    s.add(m);
  }
  return pmrem.fromScene(s, 0, 0.1, 50).texture;
}
function bgTexture(stops) {
  const c = canvas(540, 960);
  const x = c.getContext("2d");
  const g = x.createRadialGradient(270, 430, 0, 270, 470, 680);
  stops.forEach(([o, col]) => g.addColorStop(o, col));
