  set(line, { fontSize: `${size}px`, color });
  const letters = [...text].map((ch) => {
    const m = el("span", "mask", line);
    return el("span", "ch", m, ch === " " ? " " : ch);
  });
  return { line, letters };
}
// outDir -1 leaves upward, 1 downward.
function revealWord(w, t, t0, { dur = 0.5, stagger = 0.03, out = 1e6, outDir = -1, outDur = 0.32 } = {}) {
  let any = false;
  w.letters.forEach((l, i) => {
    const e = expoOut(span(t, t0 + i * stagger, t0 + i * stagger + dur));
    const x = easeIn(span(t, out + i * stagger * 0.6, out + i * stagger * 0.6 + outDur));
    const y = (1 - e) * 112 + x * 112 * outDir;
    l.style.transform = `translateY(${f2(y)}%)`;
    if (e > 0 && x < 1) any = true;
  });
  w.line.style.visibility = any ? "visible" : "hidden";
}
const GLYPHS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/+#";
function scramble(text, p, seed) {
  let s = "";
  [...text].forEach((ch, i) => {
    const at = (i + 1) / text.length;
    if (ch === " " || p >= at) s += ch === " " ? " " : ch;
    else if (p > at - 0.3) s += GLYPHS[Math.floor(rand(seed + i * 7.3 + Math.floor(p * 24)) * GLYPHS.length)];
    else s += " ";
  });
  return s;
}
function label(n, t, t0, text, { dur = 0.45, out = 1e6, seed = 1 } = {}) {
  const p = span(t, t0, t0 + dur);
  const o = 1 - span(t, out, out + 0.2);
  n.textContent = scramble(text, p, seed);
  n.style.opacity = f2(t >= t0 ? o : 0);
}

