    const l = el("div", "mono role", r);
    set(l, { top: "1268px" });
    H.proof = { r, l };
  }
  // 05: Magik Management's lines, from its own site.
  {
    const r = el("div", "layer");
    const tags = [["BUILD THE", "BRAND."], ["CREATE", "DEMAND."], ["DRIVE", "GROWTH."]].map(([a, b]) => {
      const l1 = bigWord(r, a, 178);
      const l2 = bigWord(r, b, 178, { color: "var(--gold)" });
      set(l1.line, { left: "90px", top: "300px" });
      set(l2.line, { left: "90px", top: `${300 + 0.72 * 178 + 22}px` });
      return { l1, l2 };
    });
    H.house = { r, tags };
  }
  // 06: the call, then the end card.
  {
    const r = el("div", "layer");
    const dm = bigWord(r, "DM ME", 220);
    const br = bigWord(r, "“BRAND”", 220, { color: "var(--gold)" });
    set(dm.line, { left: "90px", top: "326px" });
    set(br.line, { left: "90px", top: `${326 + 0.72 * 220 + 22}px` });
    H.call = { r, dm, br };
  }
  {
    const r = el("div", "layer");
    const mono = canvas(560, 480);
    const mx = mono.getContext("2d");
    const sw = O.logo.width * 0.268;
    const s = 480 / O.logo.height;
    mx.drawImage(O.logo, 0, 0, sw, O.logo.height, (560 - sw * s) / 2, 0, sw * s, 480);
    mx.globalCompositeOperation = "source-in";
    mx.fillStyle = "#F4C752";
    mx.fillRect(0, 0, 560, 480);
    const mark = el("img", "mark", r);
    mark.src = mono.toDataURL();
    const name = bigWord(r, "CINEN HAMILA", 206);
    set(name.line, { left: "0", width: "1080px", textAlign: "center", top: "862px" });
    const bdg = el("div", "bdg", r);
    bdg.innerHTML = badgeSvg(62);
    const role = el("div", "mono role gold", r);
    set(role, { top: "1052px" });
    const handle = el("div", "mono role dim", r);
    set(handle, { top: "1106px" });
    const rule = el("div", "endrule", r);
    const right = name.letters[name.letters.length - 1].parentElement.getBoundingClientRect().right;
    set(bdg, { left: `${right + 14}px`, top: "872px" });
    H.end = { r, mark, name, bdg, role, handle, rule };
  }
  H.vignette = el("div", "vignette");
  const grain = el("div", "grain");
  const gc = canvas(256, 256);
  const gx = gc.getContext("2d");
  const im = gx.createImageData(256, 256);
  for (let i = 0; i < 256 * 256; i++) {
    const v = Math.floor(rand(i * 1.37 + 3) * 255);
    im.data.set([v, v, v, 255], i * 4);
  }
  gx.putImageData(im, 0, 0);
  set(grain, { backgroundImage: `url(${gc.toDataURL()})`, backgroundSize: "256px 256px" });
  H.grain = grain;
  // CONTENT's letters carry the photo collage, each offset to its place in the word.
  const content = H.method.lines[3].w;
  const lw = content.line.getBoundingClientRect().width;
  content.letters.forEach((l) => {
    const x = l.parentElement.offsetLeft;
    set(l, { backgroundImage: `url(${H.photoUrl})`, backgroundSize: `${f2(lw * 1.6)}px auto`, backgroundPosition: `${f2(-x)}px 50%` });
    l.dataset.x = x;
  });
  H.contentW = lw;
};

// ---------------------------------------------------------------------------------------
function setScreen(texKey, intensity = 1, zoom = 1) {
  const P = O.phone;
  const t = O.tex[texKey];
  if (P.disp.emissiveMap !== t) P.disp.emissiveMap = t;
  P.disp.emissiveIntensity = intensity;
  t.center.set(0.5, 0.5);
  t.repeat.set(1 / zoom, 1 / zoom);
}
async function updateSite(t) {
  const url = M.frame("mobile", clamp(0.3 + Math.max(0, t - T.house + 0.4) * 1.15, 0, 21.9));
  if (url === O.site.last) return;
  const im = await loadImg(url);
  drawSite(O.siteCanvas.getContext("2d"), im, O.siteCanvas.width / UI0.W);
  O.tex.site.needsUpdate = true;
  O.site.last = url;
}
function updateDM(t) {
  const typed = T.keys.filter((k) => t >= k).length;
  const sent = t >= T.send;
  const pressI = T.keys.findIndex((k) => t >= k && t < k + 0.11);
  const s = { typed: sent ? 0 : typed, sent, seen: t >= T.seen, typing: t >= T.typing && t < T.reply, reply: t >= T.reply, press: pressI >= 0 ? "BRAND"[pressI] : null };
  if (t >= T.send && t < T.send + 0.12) s.press = "return";
  const key = JSON.stringify(s);
  if (key === O.dm.last) return;
  drawDM(O.dmCanvas.getContext("2d"), O.img, O.dmCanvas.width / UI0.W, s);
  O.tex.dm.needsUpdate = true;
  O.dm.last = key;
}
function hideAll() {
  O.phone.g.visible = false;
  O.phone.layers.forEach((m) => (m.visible = false));
  O.ceo.g.visible = O.counter.visible = false;
  O.cards.forEach((c) => (c.visible = false));
  for (const k of ["name", "method", "proof", "house", "call", "end"]) H[k].r.style.display = "none";
  scene.environment = O.envPhone;
  scene.environmentRotation.set(0, 0, 0);
  scene.environmentIntensity = 1;
  bokeh.enabled = false;
  bloom.strength = 0.12;
  camera.fov = 30;
}

// 1. The object: macro on the lenses, along the titanium, the turn to the screen, his profile
//    lifting off in layers on the double kick, then the push into his photo.
function s1(t) {
  const P = O.phone;
  P.g.visible = true;
  P.g.position.set(0, 0, 0);
  if (t < T.macro2) {
    const p = t / T.macro2;
    setScreen("profile", 0);
    P.g.rotation.set(0.2, Math.PI - 0.38 + 0.06 * p, 0.05);
    const tgt = closeUp(P.g, P.lens, V(0, 0, -1), lerp(0.43, 0.36, p), V(lerp(0.07, 0.02, p), lerp(0.05, 0.015, p), 0));
    scene.environmentRotation.set(0, -0.9 + 0.9 * p, 0);
    bokeh.enabled = true;
    bokeh.uniforms.focus.value = camera.position.distanceTo(tgt);
    bokeh.uniforms.aperture.value = 0.09;
    bokeh.uniforms.maxblur.value = 0.006;
    return;
  }
  if (t < T.turn) {
    const p = span(t, T.macro2, T.turn);
    setScreen("profile", 0);
    P.g.rotation.set(0.05, 1.08, 0.07);
    const y = lerp(0.5, 0.0, cubicInOut(p));
    const tgt = closeUp(P.g, V(-PW / 2, y, 0), V(-1, 0, 0.5), 0.6);
    scene.environmentRotation.set(0, 0.7 - 1.4 * p, 0);
    bokeh.enabled = true;
    bokeh.uniforms.focus.value = camera.position.distanceTo(tgt);
    bokeh.uniforms.aperture.value = 0.06;
    bokeh.uniforms.maxblur.value = 0.005;
    return;
  }
  // The turn.
  const p = cubicInOut(span(t, T.turn, 3.22));
  const wake = easeOut(span(t, T.wake, T.wake + 0.45));
  const exploded = t >= T.pop1;
  setScreen(exploded ? "base" : "profile", wake, lerp(1.06, 1, wake));
  const sway = cubicInOut(span(t, 3.3, 4.55));
  P.g.rotation.set(lerp(0.3, 0.04, p) + 0.26 * sway, lerp(Math.PI + 0.8, -0.1, p) - 0.62 * sway, lerp(-0.12, 0, p) + 0.05 * sway);
  scene.environmentRotation.set(0, lerp(-0.6, 0.25, p) + 0.3 * sway, 0);
  // The layers.
  P.layers.forEach((m) => {
    const at = m.userData.group ? T.pop2 : T.pop1;
    const e = t >= at ? backOut(span(t, at, at + 0.42), 1.3) : 0;
    m.visible = exploded;
    m.position.copy(m.userData.home);
    m.position.z += m.userData.depth * e;
    m.userData.card.material.opacity = clamp(e * 3);
  });
  const d = lerp(2.5, 4.7, p) - 0.55 * sway;
  const camWide = { pos: V(0, 0.04 + 0.25 * sway, d), tgt: V(0, 0.02, 0) };
  if (t < T.push) {
    lookAt(camWide.pos, camWide.tgt);
    return;
  }
  // Push into his photo, accelerating into the cut.
  const q = cubicIn(span(t, T.push, T.name));
  P.g.updateMatrixWorld(true);
  const av = P.layers[1];
  const avW = av.getWorldPosition(new THREE.Vector3());
  const n = V(0, 0, 1).applyQuaternion(P.g.quaternion);
  const close = avW.clone().add(n.multiplyScalar(0.32));
  lookAt(camWide.pos.clone().lerp(close, q), camWide.tgt.clone().lerp(avW, Math.min(1, q * 1.6)));
}

// 2. His name, full width; it splits and CEO flies in, in gold; each letter flips on the
//    double kick; the camera dives through the O.
function s2(t) {
  const N = H.name;
  N.r.style.display = "block";
  revealWord(N.cinen, t, T.name, { out: T.split, outDir: -1 });
  revealWord(N.hamila, t, T.hamila, { out: T.split, outDir: 1 });
  label(N.role, t, T.role, "CEO · MAGIK MANAGEMENT", { out: T.split - 0.12, seed: 3 });
  label(N.of, t, T.of, "OF MAGIK MANAGEMENT", { out: T.dive, seed: 5 });
  if (t < T.split) return;
  scene.environment = O.envType;
  scene.environmentIntensity = 1.3;
  const C = O.ceo;
  C.g.visible = true;
  const fly = expoOut(span(t, T.split, T.land + 0.25));
  C.g.position.set(0, 0.06, lerp(-9, 0, fly));
  C.g.rotation.set(lerp(0.45, 0, fly), lerp(1.4, 0, fly) + 0.06 * Math.sin((t - T.split) * 1.1), 0);
  C.letters.forEach((l, i) => {
    const a = T.flip + [0, 0.07, 0.19][i];
    l.rotation.x = -Math.PI * 2 * expoOut(span(t, a, a + 0.5));
  });
  scene.environmentRotation.set(0, lerp(-0.5, 0.4, span(t, T.split, T.method)), 0);
  bloom.strength = 0.16;
  const orbit = lerp(-0.22, 0.24, cubicInOut(span(t, T.land, T.dive + 0.2)));
  const base = V(Math.sin(orbit) * 4.3, 0.12, Math.cos(orbit) * 4.3);
  if (t < T.dive) {
    lookAt(base, V(0, 0.02, 0));
    return;
  }
  // Through the O's counter.
  C.g.updateMatrixWorld(true);
  const oc = C.letters[2].getWorldPosition(new THREE.Vector3());
  const q = span(t, T.dive, T.method);
  const front = oc.clone().add(V(0, 0, 0.9));
  const behind = oc.clone().add(V(0, 0, -0.4));
  const a = cubicInOut(Math.min(1, q / 0.55));
  const b = cubicIn(clamp((q - 0.55) / 0.45));
  const pos = base.clone().lerp(front, a).lerp(behind, b);
  lookAt(pos, V(0, 0.02, 0).lerp(oc, a).add(V(0, 0, -1.0 * b)));
}

// 3. The method: his line as a stack of words that fill the width, each on the beat.
function s3(t) {
  const Mth = H.method;
  Mth.r.style.display = "block";
  label(Mth.lead, t, T.method, "I HELP", { seed: 8 });
  const L = Mth.lines;
  L.forEach((l, i) => revealWord(l.w, t, l.at, { dur: 0.45, stagger: 0.025 }));
  // Scroll: the newest line sits in view; the whole stack centres while it is short.
  const target = (i) => {
    const h = L[i].bottom - 0;
    return h < 1060 ? 830 - h / 2 : 1390 - L[i].bottom;
  };
  let off = target(0);
  for (let i = 1; i < L.length; i++) off = lerp(off, target(i), expoOut(span(t, L[i].at, L[i].at + 0.5)));
  const exit = cubicIn(span(t, T.out3, T.proof));
  off -= 1900 * exit;
  Mth.stack.style.transform = `translateY(${f2(off)}px)`;
  // CLIENTS. punches on the double kick; CONTENT's photos drift.
  const k = (a) => (t >= a ? Math.exp(-(t - a) * 10) : 0);
  const punch = 1 + 0.07 * (k(13.96) + k(14.15));
  L[5].w.line.style.transform = `scale(${punch.toFixed(4)})`;
  const pan = -(t - 12.5) * 60;
  L[3].w.letters.forEach((l) => (l.style.backgroundPosition = `${f2(-Number(l.dataset.x) + pan)}px 50%`));
}

// 4. The proof: a gold counter runs to 300, the + lands, his photos float behind; on the fill
//    the digits fly apart and the phone comes through.
function s4(t) {
  scene.environment = O.envType;
  scene.environmentIntensity = 1.3;
  const C = O.counter;
  C.visible = true;
  const v = Math.round(300 * quartOut(span(t, T.proof, T.plus - 0.05)));
  const digits = [Math.floor(v / 100), Math.floor(v / 10) % 10, v % 10];
  O.slots.forEach((s, i) => (s.m.geometry = O.digits[digits[i]].geo));
  const pl = t >= T.plus ? backOut(span(t, T.plus, T.plus + 0.4), 1.8) : 0;
  O.plus.visible = t >= T.plus;
  O.plus.scale.setScalar(0.6 * Math.max(0.001, pl));
  O.plus.rotation.y = (1 - Math.min(1, pl)) * -1.6;
  // The fill scatters them.
  const parts = [...O.slots.map((s) => s.pivot), O.plus];
  const dirs = [V(-1.6, 0.9, 2.6), V(0.3, -1.4, 3.0), V(1.7, 0.6, 2.4), V(1.2, 1.6, 2.2)];
  const hits = [19.76, 20.09, 20.31, 20.55];
  parts.forEach((p, i) => {
    const s = easeIn(span(t, hits[i], hits[i] + 0.55));
    p.position.copy(p.userData.home).add(dirs[i].clone().multiplyScalar(s));
    p.rotation.set(s * 2.4 * (i % 2 ? 1 : -1), s * 3.1, s * 0.8);
  });
  C.rotation.set(0.06, lerp(0.32, 0.1, span(t, T.proof, T.fill)), 0.0);
  C.position.set(O.plusW / 2 * (1 - expoOut(span(t, T.plus, T.plus + 0.4))), 0.12, 0);
  scene.environmentRotation.set(0, lerp(-0.45, -0.22, span(t, T.proof, T.house)), 0);
  bloom.strength = 0.16;
  O.cards.forEach((c, i) => {
    c.visible = true;
    c.material.opacity = 1 - span(t, 20.4, 21.0);
    c.position.copy(c.userData.home);
    c.position.y += 0.06 * (t - T.proof) * (i % 2 ? 1 : -1);
    c.rotation.set(0, c.userData.spin + 0.05 * (t - T.proof), 0);
  });
  const zoom = 1 + 0.08 * expoOut(span(t, T.dk1, T.dk1 + 0.08)) + 0.08 * expoOut(span(t, T.dk2, T.dk2 + 0.08));
  const pull = cubicInOut(span(t, T.proof, T.dk1));
  const d = lerp(3.9, 4.6, pull) / zoom;
  bokeh.enabled = true;
  bokeh.uniforms.focus.value = d;
  bokeh.uniforms.aperture.value = 0.02 * (1 - span(t, 20.3, 21.0));
  bokeh.uniforms.maxblur.value = 0.009;
  const ang = lerp(0.18, -0.12, pull);
  lookAt(V(Math.sin(ang) * d, lerp(-0.18, 0.08, pull), Math.cos(ang) * d), V(0, 0.08, 0));
  const P = H.proof;
  P.r.style.display = "block";
  label(P.l, t, T.label4, "CLIENTS UNDER MANAGEMENT", { out: T.fill, seed: 11 });
  // The phone arrives from the dark behind.
  if (t >= 20.0) {
    const Ph = O.phone;
    Ph.g.visible = true;
    setScreen("site", 1);
    const a = expoOut(span(t, 20.2, T.house + 0.5));
    Ph.g.position.set(0, lerp(-0.6, 0, a), lerp(-12, 0, a));
    Ph.g.rotation.set(lerp(0.7, 0.06, a), lerp(-2.4, -0.32, a), lerp(0.3, 0.02, a));
    const camB = { pos: V(0, 0.27, 5.0), tgt: V(0, 0.27, 0) };
    const m = cubicInOut(span(t, 20.4, T.house));
    lookAt(camera.position.clone().lerp(camB.pos, m), V(0, 0.08, 0).lerp(camB.tgt, m));
  }
}

// 5. The house: the phone with Magik Management's site, its three lines, three angles on the
//    groove, then into the screen.
function s5(t) {
  const P = O.phone;
  P.g.visible = true;
  setScreen("site", 1);
  const R = H.house;
  R.r.style.display = "block";
  R.tags.forEach((g, i) => {
    const out = i < 2 ? T.tag[i + 1] - 0.3 : T.into;
    revealWord(g.l1, t, T.tag[i], { out });
    revealWord(g.l2, t, T.tag[i] + 0.12, { out: out + 0.04 });
  });
  scene.environmentRotation.set(0, lerp(-0.7, 0.7, span(t, T.house, T.call)), 0);
  if (t < T.tag[1]) {
    const a = expoOut(span(t, T.house - 0.9, T.house + 0.5));
    const p = span(t, T.house, T.tag[1]);
    P.g.position.set(0, 0, 0);
    P.g.rotation.set(0.06 + 0.04 * p, lerp(-0.32, -0.14, p), 0.02);
    lookAt(V(0.05 * p, 0.27, 5.0 - 0.25 * p), V(0, 0.27, 0));
    return;
  }
  if (t < T.tag[2]) {
    const p = span(t, T.tag[1], T.tag[2]);
    P.g.position.set(0, 0, 0);
    P.g.rotation.set(0.42, lerp(0.5, 0.36, p), -0.08);
    lookAt(V(0.05, 0.47, lerp(4.0, 3.75, p)), V(0, 0.42, 0));
    return;
  }
  if (t < T.into) {
    const p = span(t, T.tag[2], T.into);
    P.g.position.set(0, 0, 0);
    P.g.rotation.set(-0.06, lerp(-0.55, -0.4, p), 0.04);
    lookAt(V(lerp(0.55, 0.4, p), -0.95, 4.3), V(0, 0.32, 0));
    return;
  }
  // Square on, then into the screen until it fills the frame.
  const p = cubicInOut(span(t, T.into, T.call));
  P.g.position.set(0, 0, 0);
  P.g.rotation.set(lerp(-0.06, 0, p), lerp(-0.4, 0, p), lerp(0.04, 0, p));
  const from = { pos: V(0.4, -0.95, 4.3), tgt: V(0, 0.32, 0) };
  lookAt(from.pos.clone().lerp(V(0, 0, PD / 2 + 1.75), p), from.tgt.clone().lerp(V(0, 0, 0), p));
}

// 6. The call: out of the screen onto the DM thread, BRAND typed and sent, his reply; then the
//    phone turns away and the end card lands on the last hit.
function s6(t) {
  const P = O.phone;
  updateDM(t);
  const C = H.call;
  C.r.style.display = "block";
  revealWord(C.dm, t, T.dmme, { out: T.end });
  revealWord(C.br, t, T.send, { out: T.end + 0.05 });
  scene.environmentRotation.set(0, lerp(0.5, -0.3, span(t, T.call, T.end)), 0);
  if (t < T.end + 0.9) {
    P.g.visible = true;
    setScreen("dm", 1);
    const back = cubicInOut(span(t, T.call, T.call + 0.75));
    const leave = cubicIn(span(t, T.end, T.end + 0.85));
    P.g.position.set(0, -2.6 * leave, 0);
    P.g.rotation.set(lerp(0, 0.08, back) + 0.5 * leave, lerp(0, -0.16, back) + Math.PI * 1.2 * leave, lerp(0, 0.02, back));
    const far = { pos: V(0.04, 0.45, 4.75), tgt: V(0, 0.45, 0) };
    lookAt(V(0, 0, PD / 2 + 1.75).lerp(far.pos, back), V(0, 0, 0).lerp(far.tgt, back));
  }
  if (t < T.end + 0.15) return;
  const E = H.end;
  E.r.style.display = "block";
  const mk = expoOut(span(t, T.end + 0.3, T.end + 0.9));
  set(E.mark, { opacity: f2(mk), transform: `translateY(${f2((1 - mk) * 30)}px)` });
  revealWord(E.name, t, T.end + 0.42, { stagger: 0.028 });
  const bp = t >= T.end + 0.95 ? backOut(span(t, T.end + 0.95, T.end + 1.3), 2) : 0;
  set(E.bdg, { transform: `scale(${Math.max(0, bp).toFixed(3)})` });
  label(E.role, t, T.end + 1.0, "CEO · MAGIK MANAGEMENT", { seed: 14 });
  label(E.handle, t, T.end + 1.25, "@THECINENHAMILA", { seed: 17 });
  const rp = expoOut(span(t, T.hit, T.hit + 0.5));
  set(E.rule, { transform: `scaleX(${rp.toFixed(4)})` });
}

window.render = async (t) => {
  const f = Math.round(t * D.fps);
  H.grain.style.backgroundPosition = `${Math.floor(rand(f) * 256)}px ${Math.floor(rand(f + 77) * 256)}px`;
  hideAll();
  // The running label.
  let si = -1;
  SECTIONS.forEach(([a], i) => (t >= a ? (si = i) : 0));
  const txt = si >= 0 ? SECTIONS[si][1] : "";
  if (txt) {
    H.hud.style.display = "block";
    H.hud.textContent = scramble(txt, span(t, SECTIONS[si][0], SECTIONS[si][0] + 0.4), 20 + si);
    H.rule.style.display = "block";
    H.rule.style.transform = `scaleX(${expoOut(span(t, T.hud, T.hud + 0.7)).toFixed(4)})`;
  } else H.hud.style.display = H.rule.style.display = "none";
  if (t < T.name) s1(t);
  else if (t < T.method) s2(t);
  else if (t < T.proof) s3(t);
  else if (t < T.house) s4(t);
  else if (t < T.call) {
    await updateSite(t);
    s5(t);
  } else s6(t);
  if (t >= 20.0 && t < T.house) await updateSite(t);
  camera.updateProjectionMatrix();
  composer.render();
};
